mapper.select:
		select
		
		from datadictionaryname n left join datadictionaryvalue v on n.id =
		v.datadictid

		
			n.isvalid = 1 and v.isvalid=1
			
				and v.id = #{dictValueId}
			
			
				and n.id = #{dictNameId}
			
			
				and v.dataDictValue = #{dataDictValue}
			
			
				and n.datadictname= #{dataDictName}
